import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
// font atlas import not needed in code, but ctx.fontAtlas used

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Extract text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || { text: 'Journal 1', role: 'headline' };
  const headlineText = headlineItem.text || 'Journal 1';

  // --- Background plane ---
  // Use atlas region aspect: 512x320 = 1.6
  const planeWidth = 2.0;
  const planeHeight = planeWidth * (320 / 512); // 1.25
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface fallback
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = 0;

  // --- Load texture asynchronously ---
  ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
    // Set texture repeat and offset if needed (full atlas region)
    // Source rect: 0,0,512,320 → entire texture, no offset
    material.map = tex;
    material.needsUpdate = true;
  });

  group.add(plane);

  // --- Text overlay ---
  const textGroup = ctx.fontAtlas.createText(headlineText, {
    fontSize: 39,
    color: '#e8ecf2', // paper
    align: 'center',
    maxWidthPx: planeWidth * 100, // generous
  });
  // Scale text to match plane size (text is in unit size relative to fontSize)
  // We want the text to fit within the plane. Font size 39px is quite large; we'll scale it.
  textGroup.scale.set(0.01, 0.01, 0.01); // typical scale for MSDF text to scene units
  textGroup.position.z = 0.01; // slight front
  group.add(textGroup);

  // --- Set explicit position from spec ---
  group.position.set(-3.2, 1, 0.06);

  // --- Track elements for cleanup ---
  const disposables = [geometry, material, textGroup];

  // --- User data ---
  group.userData.cleanup = () => {
    // Dispose plane
    plane.geometry.dispose();
    plane.material.dispose();
    if (plane.material.map) plane.material.map.dispose();

    // Dispose text meshes (traverse text group)
    textGroup.traverse(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  // No primitives to apply
  // No event handlers

  return group;
}
